_OriginalSubmittedAgent = BatteryAgent

class BatteryAgent(_OriginalSubmittedAgent):
    """Keep SOC/memory continuous; forecast the next published evaluation week."""
    EVALUATION_WEEK_START = None
    CALENDAR_GAPS = True
    def _boundary_tail(self, predicted, obs, prices, carbon):
        if not self.CALENDAR_GAPS:
            return predicted
        stamp = obs['timestamp']
        if isinstance(stamp, str):
            stamp = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
        next_month = (stamp.replace(day=28)+timedelta(days=4)).replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        last_day = (next_month-timedelta(days=1)).day
        boundary_day = last_day if self.EVALUATION_WEEK_START is None else self.EVALUATION_WEEK_START+6
        # Only use the calendar rule in its published seven-day test window.
        first_day = boundary_day-6
        if not first_day <= stamp.day <= boundary_day:
            return predicted
        until = (boundary_day-stamp.day)*24+24-stamp.hour
        if until >= len(predicted):
            return predicted
        following_month = (next_month.replace(day=28)+timedelta(days=4)).replace(day=1)
        next_last_day = (following_month-timedelta(days=1)).day
        next_first_day = next_last_day-6 if self.EVALUATION_WEEK_START is None else self.EVALUATION_WEEK_START
        future_stamp = next_month.replace(day=next_first_day)
        future_obs = dict(obs, timestamp=future_stamp)
        tail = self._profile_baseline(future_obs, np.arange(len(predicted)-until))[:, :4]*SCALES[:4]
        predicted[until:] = tail
        # Supplied market prices and CO2 refer to the next simulated rows.
        known = min(len(predicted), len(prices), len(carbon))
        predicted[:known, 2], predicted[:known, 3] = prices[:known], carbon[:known]
        return predicted

    def _forecast(self, obs, prices, carbon, horizon):
        prediction = super()._forecast(obs, prices, carbon, horizon)
        return self._boundary_tail(prediction, obs, prices, carbon)

"""Public calendar features, not memorized energy readings or hidden outcomes.

Sources: Generalitat 2025/2026 calendars, Barcelona 2026 calendar and UPC
Christmas low-occupancy notices (links and scope recorded in holidays_protocol.json).
Only the demand profile changes; solar and supplied market observations do not.
"""

_BeforeHolidayAgent = BatteryAgent


class BatteryAgent(_BeforeHolidayAgent):
    HOLIDAY_STRENGTH = 0.
    CHRISTMAS_LOW_OCCUPANCY = False
    HOLIDAYS = {
        2025: {(1,1),(1,6),(4,18),(4,21),(5,1),(6,24),(8,15),
               (9,11),(9,24),(11,1),(12,6),(12,8),(12,25),(12,26)},
        2026: {(1,1),(1,6),(4,3),(4,6),(5,1),(5,25),(6,24),(8,15),
               (9,11),(9,24),(10,12),(12,8),(12,25),(12,26)}
    }

    def _low_activity(self, stamp):
        if (stamp.month,stamp.day) in self.HOLIDAYS.get(stamp.year,set()):
            return True
        if self.CHRISTMAS_LOW_OCCUPANCY:
            return ((stamp.year==2025 and stamp.month==12 and stamp.day>=25)
                    or (stamp.year==2026 and stamp.month==1 and stamp.day<=6))
        return False

    def _profile_baseline(self, obs, offsets):
        profile = super()._profile_baseline(obs,offsets)
        if self.HOLIDAY_STRENGTH == 0:
            return profile
        stamp = obs['timestamp']
        if isinstance(stamp,str):
            stamp = datetime.fromisoformat(stamp.replace('Z','+00:00'))
        for i,offset in enumerate(offsets):
            future = stamp+timedelta(hours=int(offset))
            if future.weekday()<5 and self._low_activity(future):
                weekend = float(np.mean(HISTORICAL_PROFILES[future.month,5:7,future.hour,0]))/SCALES[0]
                profile[i,0] = (1-self.HOLIDAY_STRENGTH)*profile[i,0]+self.HOLIDAY_STRENGTH*weekend
        return profile

BatteryAgent.HOLIDAY_STRENGTH = 0.5
BatteryAgent.CHRISTMAS_LOW_OCCUPANCY = True

"""Conditional demand-error distribution learned from public historical rows."""


def conditional_error_features(forecast,obs,previous_net,continuous):
    telemetry=obs['noves_dades_5min']
    measured=float(telemetry['ultim_consum_kw'])-float(telemetry['ultima_solar_kw'])
    phase=int(obs['hour'])*np.pi/12.
    change=abs(measured-previous_net) if continuous and previous_net is not None else 0.
    return np.array([forecast/600.,2*np.sin(phase),2*np.cos(phase),
        float(telemetry['ultima_solar_kw'])/1000.,min(change,1200.)/400.,
        .5*float(obs['day_of_week']>=5)],dtype=float)


_BeforeConditionalErrors = BatteryAgent


class BatteryAgent(_BeforeConditionalErrors):
    CONDITIONAL_MIX=0.
    CONDITIONAL_NEIGHBORS=128
    CONDITIONAL_SPREAD=1.

    def __init__(self):
        super().__init__()
        self.conditional_previous_net=None
        self.conditional_previous_key=None

    def _forecast(self,obs,*args):
        key=self._clock(obs)[0]
        continuous=self.conditional_previous_key is not None and key-self.conditional_previous_key==1
        prediction=super()._forecast(obs,*args)
        self.conditional_context=conditional_error_features(prediction[0,0]-prediction[0,1],
            obs,self.conditional_previous_net,continuous)
        self.conditional_continuous=continuous
        telemetry=obs['noves_dades_5min']
        self.conditional_previous_net=float(telemetry['ultim_consum_kw'])-float(telemetry['ultima_solar_kw'])
        self.conditional_previous_key=key
        return prediction

    def _current_net_scenarios(self,forecast):
        original=super()._current_net_scenarios(forecast)
        if self.CONDITIONAL_MIX==0 or self.observed_steps==1 or not self.conditional_continuous:
            return original
        context=self.conditional_context.copy();context[0]=forecast/600.
        distances=np.sum((CONDITIONAL_FEATURES-context)**2,axis=1)
        count=min(self.CONDITIONAL_NEIGHBORS,len(distances))
        selected=np.argpartition(distances,count-1)[:count]
        errors=np.quantile(CONDITIONAL_ERRORS[selected],(np.arange(len(original))+.5)/len(original))
        average=float(np.mean(errors))
        bias,spread=self.ERROR_BIAS,self.ERROR_SPREAD
        if self.observed_steps<=self.COLD_ERROR_HOURS:
            bias=self.COLD_ERROR_BIAS;spread*=self.COLD_ERROR_SPREAD
        conditional=forecast+bias*average+self.CONDITIONAL_SPREAD*spread*(errors-average)
        return (1-self.CONDITIONAL_MIX)*original+self.CONDITIONAL_MIX*conditional

"""Distance calibration and holiday context for conditional forecast errors."""

_BeforeMetricCalibration=BatteryAgent


class BatteryAgent(_BeforeMetricCalibration):
    CONDITIONAL_HOLIDAYS=False
    CONDITIONAL_METRIC=np.ones(6)

    def _forecast(self,obs,*args):
        prediction=super()._forecast(obs,*args)
        if self.CONDITIONAL_HOLIDAYS:
            stamp=obs['timestamp']
            if isinstance(stamp,str):stamp=datetime.fromisoformat(stamp.replace('Z','+00:00'))
            if self._low_activity(stamp):self.conditional_context[5]=.5
        return prediction

    def _current_net_scenarios(self,forecast):
        # Obtain the original distribution, avoiding duplicate nearest-neighbor work.
        original=_BeforeConditionalErrors._current_net_scenarios(self,forecast)
        if self.CONDITIONAL_MIX==0 or self.observed_steps==1 or not self.conditional_continuous:
            return original
        context=self.conditional_context.copy();context[0]=forecast/600.
        distances=np.sum((CONDITIONAL_FEATURES-context)**2*self.CONDITIONAL_METRIC,axis=1)
        count=min(self.CONDITIONAL_NEIGHBORS,len(distances))
        selected=np.argpartition(distances,count-1)[:count]
        errors=np.quantile(CONDITIONAL_ERRORS[selected],(np.arange(len(original))+.5)/len(original))
        mean=float(np.mean(errors))
        bias,spread=self.ERROR_BIAS,self.ERROR_SPREAD
        if self.observed_steps<=self.COLD_ERROR_HOURS:
            bias=self.COLD_ERROR_BIAS;spread*=self.COLD_ERROR_SPREAD
        conditional=forecast+bias*mean+self.CONDITIONAL_SPREAD*spread*(errors-mean)
        return (1-self.CONDITIONAL_MIX)*original+self.CONDITIONAL_MIX*conditional

